export const prepareStringToBeValidFilename = (str) => str
    ? str
        .replaceAll(' ', '-')
        .replace(/\{.*?\}/g, '-') // remove path parameters
        .replace(/^-/, '')
        .replace(/-$/, '')
        .replace(/[{}(),.'\n\/]/g, '') // remove special characters
        .replaceAll(/--/g, '-') // replace double hyphens
        .toLowerCase()
    : undefined;
export const generateUniqueFilenameWithoutExtension = (pages, base) => {
    const hasFilename = (filename) => {
        const candidate = filename.toLowerCase();
        return Array.isArray(pages)
            ? pages.includes(candidate)
            : Object.prototype.hasOwnProperty.call(pages, candidate);
    };
    let filename = base;
    if (hasFilename(filename)) {
        let extension = 1;
        filename = `${base}-${extension}`;
        while (hasFilename(filename)) {
            extension += 1;
            filename = `${base}-${extension}`;
        }
    }
    return filename.toLowerCase();
};
